:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-card: rgba(22, 27, 34, 0.6);
  --border-color: #30363d;
  --text-primary: #c9d1d9;
  --text-secondary: #8b949e;
  --accent-color: #00ff88; /* Electric green */
  --accent-hover: #00cc6d;
  --accent-blue: #475F91;

  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --sidebar-width: 280px;
  --nav-height: 64px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-color);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
}

h1, h2, h3, h4 {
  color: #ffffff;
  font-weight: 600;
  margin-bottom: 1rem;
  line-height: 1.2;
}

h1 { font-size: 3rem; letter-spacing: -0.02em; }
h2 { font-size: 2rem; margin-top: 2rem; }
h3 { font-size: 1.5rem; }

p { margin-bottom: 1.5rem; }

ul { margin-left: 1.5rem; margin-bottom: 1.5rem; }

/* Navigation */
.navbar {
  height: var(--nav-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2rem;
  background-color: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-brand {
  font-weight: 700;
  font-size: 1.25rem;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-links {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

.nav-links a {
  color: var(--text-secondary);
  font-weight: 500;
}

.nav-links a:hover, .nav-links a.active {
  color: #fff;
}

.nav-utilities {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* Layout */
.layout-container {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  background-color: var(--bg-primary);
  border-right: 1px solid var(--border-color);
  padding: 2rem 1.5rem;
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  transition: transform 0.3s ease, width 0.3s ease;
  flex-shrink: 0;
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
  border-right: none;
}

.sidebar h3 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

.sidebar ul {
  list-style: none;
  margin-left: 0;
}

.sidebar li a {
  display: block;
  padding: 0.5rem 0;
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.sidebar li a:hover, .sidebar li a.active {
  color: var(--accent-color);
}

.main-content {
  flex-grow: 1;
  padding: 3rem;
  max-width: 1000px;
  margin: 0 auto;
}

.sidebar-toggle {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  cursor: pointer;
  padding: 0.5rem;
  border-radius: 4px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 2rem;
  transition: all 0.2s;
}

.sidebar-toggle:hover {
  color: #fff;
  border-color: #fff;
}

/* Hero */
.hero {
  padding: 6rem 0;
  text-align: center;
}

.hero h1 {
  font-size: 4rem;
  margin-bottom: 1.5rem;
  background: linear-gradient(135deg, #fff 0%, #a5b4fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  max-width: 800px;
  margin: 0 auto 3rem;
}

.hero-ctas {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
  cursor: pointer;
}

.btn-primary {
  background-color: var(--accent-color);
  color: #000;
  border: none;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  color: #000;
  transform: translateY(-1px);
}

.btn-secondary {
  background-color: transparent;
  color: #fff;
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: #fff;
  color: #fff;
}

/* Cards & Grid */
.grid {
  display: grid;
  gap: 1.5rem;
  margin-bottom: 3rem;
}

.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-2 { grid-template-columns: repeat(2, 1fr); }

.card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s;
  backdrop-filter: blur(10px);
}

.card:hover {
  border-color: var(--accent-color);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 255, 136, 0.1);
}

.card h3 { margin-bottom: 0.5rem; }
.card p { color: var(--text-secondary); margin-bottom: 1.5rem; }
.card .cta-link {
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

/* Code & CLI Setup */
.cli-setup {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  margin-top: 3rem;
}

.tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.5rem;
}

.tab {
  background: none;
  border: none;
  color: var(--text-secondary);
  padding: 0.5rem 1rem;
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  border-radius: 4px;
}

.tab:hover { color: #fff; }
.tab.active {
  background-color: var(--border-color);
  color: #fff;
}

.accordion { margin-top: 1rem; }
.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: 8px;
  margin-bottom: 0.5rem;
  overflow: hidden;
}

.accordion-header {
  background-color: var(--bg-primary);
  padding: 1rem 1.5rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  user-select: none;
}

.accordion-header:hover { background-color: var(--bg-secondary); }
.accordion-content {
  padding: 0;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  background-color: var(--bg-card);
}

.accordion-item.active .accordion-content {
  max-height: 500px;
}

.accordion-body { padding: 1.5rem; }
.accordion-body ol { margin-left: 1.5rem; margin-bottom: 0; }
.accordion-body li { margin-bottom: 1rem; }

pre {
  background-color: #000;
  padding: 1rem;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  overflow-x: auto;
  margin: 0.5rem 0;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  color: #e6edf3;
}

code {
  font-family: var(--font-mono);
  background-color: rgba(110, 118, 129, 0.4);
  padding: 0.2em 0.4em;
  border-radius: 3px;
  font-size: 85%;
}

pre code { background-color: transparent; padding: 0; }

.keyword { color: #ff7b72; }
.string { color: #a5d6ff; }
.comment { color: #8b949e; }

/* Footer */
.footer {
  border-top: 1px solid var(--border-color);
  padding: 4rem 2rem;
  background-color: var(--bg-primary);
  margin-top: 4rem;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.footer-col h4 {
  font-size: 0.875rem;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.5rem;
}

.footer-col ul {
  list-style: none;
  margin-left: 0;
}

.footer-col li { margin-bottom: 0.75rem; }
.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}
.footer-col a:hover { color: #fff; }

/* Responsive */
@media (max-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .sidebar { width: 240px; }
}

@media (max-width: 768px) {
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .hero h1 { font-size: 2.5rem; }

  .layout-container { flex-direction: column; }
  .sidebar {
    width: 100%;
    height: auto;
    position: static;
    border-right: none;
    border-bottom: 1px solid var(--border-color);
  }

  .nav-links { display: none; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Accordion Logic
  const accordions = document.querySelectorAll('.accordion-item');
  accordions.forEach(acc => {
    const header = acc.querySelector('.accordion-header');
    header.addEventListener('click', () => {
      // Close all others
      accordions.forEach(other => {
        if (other !== acc) other.classList.remove('active');
      });
      // Toggle current
      acc.classList.toggle('active');
    });
  });

  // Package Manager Tab Logic
  const tabs = document.querySelectorAll('.tab');
  const installCodes = document.querySelectorAll('.install-cmd');

  const commands = {
    npm: 'npm i -g @commerceforge/cli@latest',
    yarn: 'yarn global add @commerceforge/cli@latest',
    pnpm: 'pnpm add -g @commerceforge/cli@latest'
  };

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      // Update active tab state
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');

      const pkg = tab.dataset.pkg;

      // Update all install command snippets
      installCodes.forEach(codeEl => {
        codeEl.textContent = commands[pkg];
      });
    });
  });

  // Sidebar Collapse Logic
  const sidebarToggles = document.querySelectorAll('.sidebar-toggle');
  const sidebar = document.querySelector('.sidebar');

  sidebarToggles.forEach(toggle => {
    toggle.addEventListener('click', () => {
      if (sidebar) {
        sidebar.classList.toggle('collapsed');
        const isCollapsed = sidebar.classList.contains('collapsed');
        toggle.innerHTML = isCollapsed ? 
          '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 18l-6-6 6-6"/></svg> Expand sidebar' : 
          '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 18l6-6-6-6"/></svg> Collapse sidebar';
      }
    });
  });
});

